# ! [allow (unused)] use std :: io :: { Read , Write } ; pub trait SolarStr { fn to_owned_string (& self) -> String ; fn len (& self) -> i32 ; } impl SolarStr for str { fn to_owned_string (& self) -> String { self . to_owned () } fn len (& self) -> i32 { self . len () as i32 } } pub trait SolarString { fn append (& mut self , s : & str) ; fn len (& self) -> i32 ; } impl SolarString for String { fn append (& mut self , s : & str) { self . push_str (s) ; } fn len (& self) -> i32 { self . len () as i32 } } pub mod mem { pub fn free < T > (p : * mut T , size : i32) { unsafe { let _ = Vec :: from_raw_parts (p , 0 , size as usize) ; } } } pub mod fs { use std :: io :: { Read , Write } ; pub fn create (path : & str) -> std :: fs :: File { std :: fs :: File :: create (path) . expect ("Failed to create file") } pub fn open (path : & str) -> std :: fs :: File { std :: fs :: File :: open (path) . expect ("Failed to open file") } pub fn read (mut f : std :: fs :: File) -> String { let mut s = String :: new () ; f . read_to_string (& mut s) . expect ("Failed to read file") ; s } pub fn write (mut f : std :: fs :: File , content : & str) { f . write_all (content . as_bytes ()) . expect ("Failed to write file") ; } pub fn write_string (mut f : std :: fs :: File , content : String) { f . write_all (content . as_bytes ()) . expect ("Failed to write file") ; } } pub fn main () { let content = std :: fs :: read_to_string ("test.txt") ; println ! ("{:?}" , content) ; }